import json, subprocess

def run(cmd):
    return subprocess.check_output(cmd, shell=True).decode("utf-8")

resources = ["deployments", "cronjobs", "configmaps", "services", "networkpolicies", "daemonsets", "statefulsets"]
for r in resources:
    out = run(f"kubectl get {r} -A -o json")
    data = json.loads(out)
    for item in data.get("items", []):
        name = item["metadata"]["name"]
        ns = item["metadata"].get("namespace", "cluster")
        last_applied = item["metadata"].get("annotations", {}).get("kubectl.kubernetes.io/last-applied-configuration")
        if last_applied:
            la_obj = json.loads(last_applied)
            print(f"=== {r} {ns}/{name} ===")
            # Compare relevant fields
            if r == "networkpolicies":
                print("  spec:", item.get("spec"))
                print("  la  :", la_obj.get("spec"))
            elif r == "configmaps":
                print("  data:", item.get("data"))
                print("  la  :", la_obj.get("data"))
            elif r == "cronjobs":
                print("  job cmd:", item["spec"]["jobTemplate"]["spec"]["template"]["spec"]["containers"][0].get("command"))
                print("  la cmd :", la_obj["spec"]["jobTemplate"]["spec"]["template"]["spec"]["containers"][0].get("command"))
            elif r == "deployments":
                print("  replicas:", item["spec"].get("replicas"), "la:", la_obj.get("spec", {}).get("replicas"))
                print("  dep cmd:", item["spec"]["template"]["spec"]["containers"][0].get("command"))
                print("  la cmd :", la_obj.get("spec", {}).get("template", {}).get("spec", {}).get("containers", [{}])[0].get("command"))
'

